class CardDragAndDropTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  setup do
    cards(:logo).update_column(:column_id, columns(:writebook_in_progress).id)
    sign_in_as(users(:david))
    visit board_url(boards(:writebook))
    assert_selector "##{dom_id(cards(:layout), :article)}", visible: :all
    assert_selector "##{dom_id(cards(:logo), :article)}", visible: :all
  end

  test "a drop moves the card before saving and preserves the column's sort order" do
    card = cards(:layout)
    destination = columns(:writebook_in_progress)
    golden_card = cards(:logo)

    assert_selector "##{dom_id(card, :article)}[draggable=true]", visible: :all
    pause_saves
    drag_card(card, dom_id(destination))

    assert_equal [ dom_id(golden_card, :article), dom_id(card, :article), dom_id(cards(:text), :article) ], card_ids_in(dom_id(destination))
    assert_equal columns(:writebook_triage), card.reload.column
    assert_selector "##{dom_id(card, :article)} .card__header .card__column-name", text: destination.name, visible: :all
    assert_no_selector ".drag-and-drop__dragged-item, .drag-and-drop__hover-container", visible: :all

    finish_save
    assert_equal destination, card.reload.column
    assert_equal [ dom_id(golden_card, :article), dom_id(card, :article), dom_id(cards(:text), :article) ], card_ids_in(dom_id(destination))
  end

  private
    def pause_saves
      page.execute_script <<~JS
        window.originalFetch = window.fetch
        window.fetch = (url, options) => {
          if (options?.method === "POST" || options?.method === "DELETE") {
            return new Promise((resolve, reject) => {
              window.finishSave = () => window.originalFetch(url, options).then(resolve, reject)
            })
          }
          return window.originalFetch(url, options)
        }
      JS
    end

    def finish_save
      page.evaluate_async_script <<~JS
        const done = arguments[arguments.length - 1]
        window.finishSave().then(() => {
          window.fetch = window.originalFetch
          done()
        })
      JS
    end

    def drag_card(card, destination_id)
      page.execute_script <<~JS, dom_id(card, :article), destination_id
        const card = document.getElementById(arguments[0])
        const destination = document.getElementById(arguments[1])
        const dataTransfer = new DataTransfer()
        card.dispatchEvent(new DragEvent("dragstart", { bubbles: true, dataTransfer }))
        destination.dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer }))
        destination.dispatchEvent(new DragEvent("drop", { bubbles: true, cancelable: true, dataTransfer }))
        card.dispatchEvent(new DragEvent("dragend", { bubbles: true, dataTransfer }))
      JS
    end

    def card_ids_in(column_id)
      page.all("##{column_id} article.card", visible: :all).map { |card| card[:id] }
    end
end
